func (q *Queries) ListPendingTransactionsByCampaign(ctx context.Context, campaignID uuid.UUID) ([]FinanceCampaignInvoice, error) {
	rows, err := q.db.Query(ctx, listPendingTransactionsByCampaign, campaignID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FinanceCampaignInvoice{}
	for rows.Next() {
		var i FinanceCampaignInvoice
		if err := rows.Scan(
			&i.ID,
			&i.CampaignID,
			&i.ContestantID,
			&i.TransactionReference,
			&i.PaymentMethod,
			&i.PaymentServiceProvider,
			&i.PaymentServiceProviderPayload,
			&i.Amount,
			&i.Currency,
			&i.InvoiceIssueDate,
			&i.InvoiceDueDate,
			&i.InvoiceDescription,
			&i.PaymentTerms,
			&i.InvoiceStatus,
			&i.PaidAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

